from collections import deque

def fill_components(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    visited = [[False]*cols for _ in range(rows)]

    # Find all connected components of 2s and 3s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] in [2, 3] and not visited[r][c]:
                # BFS to find component
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True
                has_3 = (grid[r][c] == 3)

                while queue:
                    curr_r, curr_c = queue.popleft()
                    component.append((curr_r, curr_c))
                    has_3 = has_3 or (grid[curr_r][curr_c] == 3)

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] in [2, 3]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Fill component: all cells in component get 3 if component has any 3
                for cr, cc in component:
                    result[cr][cc] = 3 if has_3 else 0

    return result

