from collections import deque

def fill_bounded_regions(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    # BFS from boundary to mark background
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                queue.append((r, c))
                visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        if not visited[r][c]:
            continue
        visited[r][c] = True

        # Expand only through non-3 cells
        if grid[r][c] != 3:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                    queue.append((nr, nc))

    # Result: 3s in place, unvisited non-3s become 3 (filled bounded regions)
    result = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                result[r][c] = 3
            elif not visited[r][c]:
                result[r][c] = 3  # Bounded region
            else:
                result[r][c] = 0  # Background

    return result

